-- Generated by `make contracts` from contracts/cdc_respnet.odcs.yaml. Do not edit: change the contract and regenerate.
-- Business rules from the contract only: total rows, renamed labels, partial places, flag meanings,
-- then the conformed condition, place and time keys (conformedDimensions). Nothing is removed or
-- changed: each rule adds a column beside the published values.
with stg as (
    select * from {{ ref('stg_cdc_respnet') }}
),

ruled as (
    select
      stg.*,
      coalesce((state IN ('Overall', 'COVID-NET', 'FluSurv-NET', 'RSV-NET')), false) AS "is_total_row",
      CASE WHEN "state" IS NULL THEN NULL ELSE 'a RESP-NET site''s catchment counties, not necessarily the whole state; the dataset doesn''t list the counties' END AS "state_partial_note"
    from stg
),

keyed as (
    select
    ruled.*,
    ruled."state" AS "_p_label",
    CASE WHEN place_state.state_fips IS NULL THEN NULL ELSE 'US-' || place_state.state_fips END AS "_p_whole",
    NULL AS "_p_decl_key",
    CASE regexp_replace(upper(trim(ruled."state")), '[.]', '', 'g') WHEN 'OVERALL' THEN 'USA' WHEN 'COVID-NET' THEN 'USA' WHEN 'FLUSURV-NET' THEN 'USA' WHEN 'RSV-NET' THEN 'USA' ELSE NULL END AS "_p_decl_parent",
    CASE regexp_replace(upper(trim(ruled."state")), '[.]', '', 'g') WHEN 'OVERALL' THEN 'all RESP-NET sites of the network combined, not the whole United States' WHEN 'COVID-NET' THEN 'all COVID-NET sites combined, not the whole United States' WHEN 'FLUSURV-NET' THEN 'all FluSurv-NET sites combined, not the whole United States' WHEN 'RSV-NET' THEN 'all RSV-NET sites combined, not the whole United States' ELSE NULL END AS "_p_decl_note",
    ruled."state_partial_note" AS "_p_note",
    cal.mmwr_year AS "_t_year",
    cal.mmwr_week AS "_t_week"
  from ruled
  left join {{ ref('stg_census_fips_state') }} as place_state
  on regexp_replace(upper(trim(ruled."state")), '[.]', '', 'g') = regexp_replace(upper(trim(place_state.state_name)), '[.]', '', 'g')
  left join {{ ref('mmwr_calendar') }} as cal
  on cast(try_cast(trim(cast(ruled."date" as varchar)) as timestamp) as date) between cal.week_start and cal.week_end
)

select
  keyed.* exclude ("_p_label", "_p_whole", "_p_decl_key", "_p_decl_parent", "_p_decl_note", "_p_note", "_t_year", "_t_week"),
  CAST(CASE WHEN keyed."surveillance_network" IS NULL THEN NULL ELSE 'cdc_respnet:' || keyed."surveillance_network" END AS VARCHAR) AS "condition_key",
  CAST(keyed."surveillance_network" AS VARCHAR) AS "condition_label",
  CAST('laboratory-confirmed (the dataset description says every counted hospitalization is laboratory-confirmed)' AS VARCHAR) AS "condition_case_status",
  CAST(NULL AS VARCHAR) AS "condition_case_subtype",
  CAST(CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_respnet:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END AS VARCHAR) AS "place_key",
  CAST(keyed._p_label AS VARCHAR) AS "place_label",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN coalesce(keyed._p_decl_parent, keyed._p_whole) ELSE NULL END AS VARCHAR) AS "place_parent_key",
  CAST(coalesce((keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)), false) AS BOOLEAN) AS "place_is_partial",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) AND coalesce(keyed._p_decl_parent, keyed._p_whole) IS NOT NULL THEN coalesce(keyed._p_decl_note, keyed._p_note) WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_respnet:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved: the contract does not declare this place label and it is not a name or code in the Census code files' ELSE NULL END AS VARCHAR) AS "place_note",
  CAST(CASE WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_respnet:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved' WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN 'partial_area' ELSE 'resolved' END AS VARCHAR) AS "place_status",
  CAST(keyed._t_year AS BIGINT) AS "mmwr_year",
  CAST(keyed._t_week AS BIGINT) AS "mmwr_week",
  CAST(CASE WHEN keyed._t_year IS NULL OR keyed._t_week IS NULL THEN NULL ELSE CAST(keyed._t_year AS VARCHAR) || '-W' || lpad(CAST(keyed._t_week AS VARCHAR), 2, '0') END AS VARCHAR) AS "time_key",
  CAST('mmwr_week' AS VARCHAR) AS "time_grain",
  CAST('the week-ending date of the admission week; season rows (date_type Season) have no week' AS VARCHAR) AS "date_basis"
from keyed
